    // ==========================================================
    // SECTION 2: 应用启动与关闭的核心动画函数 (iOS风格)
    // ==========================================================

    /**
     * 打开一个App的动画函数
     * @param {HTMLElement} iconEl - 被点击的图标元素
     * @param {HTMLElement} appView - 需要打开的应用页面元素
     */
    // index.html -> <script> 标签内
    /**
     * 打开一个App的动画函数 (V2 - 修复最终状态优先级问题)
     * @param {HTMLElement} iconEl - 被点击的图标元素
     * @param {HTMLElement} appView - 需要打开的应用页面元素
     */
    function openApp(iconEl, appView) {
        if (!appView) return;

        // 1. 动态计算变换原点 (Transform Origin) - 实现“从图标炸开”的核心
        // 使用全局变量 phoneFrame (在文件顶部定义的 .phone-frame 元素)
        if (iconEl && typeof phoneFrame !== 'undefined') {
            const iconRect = iconEl.getBoundingClientRect();
            const frameRect = phoneFrame.getBoundingClientRect();

            // 计算图标中心点相对于手机屏幕左上角的坐标
            const relativeX = iconRect.left + iconRect.width / 2 - frameRect.left;
            const relativeY = iconRect.top + iconRect.height / 2 - frameRect.top;

            // 设置到 appView 上
            appView.style.transformOrigin = `${relativeX}px ${relativeY}px`;
        } else {
            // 如果没有图标（比如直接调用），默认从中心放大
            appView.style.transformOrigin = 'center center';
        }

        // 2. 触发动画类名
        // 据 appView 的 ID (如 settings-screen) 推导类名 (如 show-settings) 并添加到 phoneFrame
        const screenId = appView.id;
        if (screenId && screenId.includes('-screen')) {
            const appId = screenId.replace('-screen', '');
            phoneFrame.classList.add(`show-${appId}`);
            
            // 特殊处理：如果是消息APP，可能需要额外的数据同步逻辑
            // (虽然已经在 click 监听器里写了，但为了保险起见，这里纯粹处理动画)
        } else {
             // 兼容旧逻辑
             appView.classList.add('active');
        }

        // 3. 图标微动反馈
        if (iconEl) {
            iconEl.style.transition = 'transform 0.1s ease';
            iconEl.style.transform = 'scale(0.85)'; // 按压感更强一点
            setTimeout(() => {
                iconEl.style.transform = 'scale(1)';
            }, 150);
        }
    }



