    charUploadInput.addEventListener('change', (event) => {
        const file = event.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (e) => {
            datingCharPortrait = e.target.result;
            charUploadBox.style.backgroundImage = `url('${datingCharPortrait}')`;
            charUploadBox.textContent = '';
            saveDatingSetup();
            checkSetupCompletion();
        };
        reader.readAsDataURL(file);
    });

    // 9. 处理背景上传
    bgUploadInput.addEventListener('change', (event) => {
        const file = event.target.files[0];
        if (!file) return;

        const tagsString = prompt("请输入此背景的标签 (多个标签请用空格或逗号隔开):", "默认");
        if (tagsString === null) return; // 用户点击了取消

        const tags = tagsString.split(/[\s,，]+/).filter(tag => tag); // 按空格或中英文逗号分割

        const reader = new FileReader();
        reader.onload = (e) => {
            const newBg = {
                url: e.target.result,
                tags: tags.length > 0 ? tags : ['未分类'],
                isDefault: false
            };
            // 如果这是上传的第一个背景，自动设为默认
            if (datingBackgrounds.length === 0) {
                newBg.isDefault = true;
            }
            datingBackgrounds.push(newBg);
            renderBgPreviews();
            saveDatingSetup();
        };
        reader.readAsDataURL(file);
    });

