    connectButton.addEventListener('click', async () => {
        const apiUrl = apiUrlInput.value.trim();
        const apiKey = apiKeyInput.value.trim();

        if (!apiUrl || !apiKey) {
            apiStatusSpan.textContent = "URL和Key不能为空";
            return;
        }

        connectButton.textContent = "connecting...";
        connectButton.disabled = true;
        apiStatusSpan.textContent = "";

        try {
            // --- START: CORRECTED LOGIC ---
            let endpointUrl = apiUrl;

            // 1. Remove any trailing slash from the user's input
            if (endpointUrl.endsWith('/')) {
                endpointUrl = endpointUrl.slice(0, -1);
            }

            // 2. Consistently append /models to the cleaned URL
            endpointUrl += '/models';
            // --- END: CORRECTED LOGIC ---

            const response = await fetch(endpointUrl, {
                headers: { 'Authorization': `Bearer ${apiKey}` }
            });


            if (!response.ok) {
                // If the response status is not 2xx, we throw a specific error
                throw new Error(`HTTP Error: ${response.status}`);
            }

            // If the request is successful...
            const data = await response.json();
            modelSelect.innerHTML = '<option value="" disabled selected>选择一个模型</option>';
            data.data.forEach(model => {
                modelSelect.innerHTML += `<option value="${model.id}">${model.id}</option>`;
            });
            modelSelect.disabled = false;
            apiStatusSpan.textContent = "✓ 连接成功";
            apiStatusSpan.style.color = "green";

        } catch (error) {
            console.error("API 连接失败:", error); // Keep detailed error for developers

            // Show different user-friendly tips based on the error type
            if (error instanceof TypeError && error.message.includes('Failed to fetch')) {
                apiStatusSpan.textContent = "✗ 网络错误或跨域问题";
                apiStatusSpan.style.color = "red";
                alert("连接失败！最常见的原因是：\n\n1. API服务器未开启CORS跨域许可。\n2. 浏览器插件拦截了请求 (如广告拦截器)。\n3. 您的网络无法访问该URL地址。");
            } else if (error.message.startsWith('HTTP Error:')) {
                const status = error.message.split(':')[1].trim();
                let tip = `(状态码: ${status})`;
                if (status === '401') {
                    tip = "✗ 认证失败 (401)，请检查您的API Key是否正确。";
                } else if (status === '404') {
                    tip = "✗ 未找到 (404)，请检查您的URL地址是否正确。";
                } else if (status >= 500) {
                    tip = `✗ 服务器错误 (${status})，API服务可能暂时不可用。`;
                } else {
                    tip = `✗ 请求失败 ${tip}，请检查API文档。`;
                }
                apiStatusSpan.textContent = tip;
                apiStatusSpan.style.color = "red";
            } else {
                apiStatusSpan.textContent = "✗ 未知错误";
                apiStatusSpan.style.color = "red";
            }

            modelSelect.innerHTML = '<option value="" disabled selected>连接失败</option>';

        } finally {
            connectButton.textContent = "Test connection";
            connectButton.disabled = false;
        }
    });

