    function translateMessageForAI(message) {
        if (!message) return null;

        // --- 1. 优先处理：聊天记录卡片 (让AI读懂转发内容) ---
        // 检查文本是否包含卡片标记
        const text = message.text || "";
        if (text.startsWith('[CHAT_HISTORY_CARD]')) {
            try {
                // 提取 JSON
                const jsonStr = text.replace('[CHAT_HISTORY_CARD]', '');
                const cardData = JSON.parse(jsonStr);

                // 构建给 AI 看的文本
                let aiText = `[系统提示：用户转发了一份聊天记录，标题为"${cardData.title}"]\n`;
                aiText += "--- 记录内容摘要 ---\n";

                // 注意：这里我们只给 AI 看预览的前4条，避免 Token 爆炸
                // 如果你希望 AI 看全量，可以在这里异步去数据库查 (但这会导致 translateMessageForAI 变成 async，牵扯太大)
                // 通常前4条 + 标题足够 AI 理解语境了。
                if (cardData.preview && Array.isArray(cardData.preview)) {
                    cardData.preview.forEach((item, index) => {
                        aiText += `${index + 1}. ${item.name}: ${item.content}\n`;
                    });
                }
                aiText += "--- 摘要结束 ---\n(如果包含更多内容，AI当前只能看到前4条)";

                return aiText;

            } catch (e) {
                return "[用户转发了一份聊天记录，但数据解析失败]";
            }
        }

        // --- 2. 【核心修复】处理引用回复 (让AI看到上下文) ---
        let replyContext = "";
        if (message.replyTo) {
            // 这里的格式是写给AI看的，怎么清楚怎么来
            replyContext = `(引用回复了 ${message.replyTo.senderName} 的话："${message.replyTo.text}")\n`;
        }

        if (message.sender === 'user') {
            // --- If the sender is the user ---
            switch (message.type) {
                case 'text':
                    return replyContext + message.text;
                case 'voice_text':
                    return message.transcript;
                case 'sticker':
                    return `[用户发送了一张表情图片：${message.text.replace('[表情包：', '').replace(']', '')}]`;

                // ▼▼▼ CORE FIX IS HERE ▼▼▼
                case 'image':
                    // 如果图片已被处理，AI就看不见它 (返回null)
                    if (message.processed) {
                        return null;
                    }
                    // 否则，AI会看到一个图片提示
                    return '[用户发送了一张图片]';
                case 'text-image':
                    // 告诉AI，用户发来的是一张文图卡片，并附上描述
                    return `[用户发送了一张文图卡片，描述为：'${message.text}']`;
                case 'file_card':
                    // 返回一个特殊对象，告诉 callAI 这是一个带文件的消息
                    // 常见的 LLM API (如 OpenAI Vision 或 Gemini) 接受 image_url 结构
                    // 注意：对于非图片文件（如 PDF），Gemini API 也通常支持通过类似结构或 inline_data 传输
                    return {
                        isMultimodal: true,
                        text: `[用户发送了一个文件：${message.fileName}，请阅读并分析它，并根据上下文做出回复]`,
                        fileUrl: message.fileUrl, // 真实的 Base64 数据
                        fileType: message.fileType // pdf, docx, etc.
                    };
                // ▲▲▲ 新增结束 ▲▲▲
                case 'action':
                    return `(旁白/动作描述：${message.text})`;

                default:
                    return message.text || null;
            }
        } else {
            switch (message.type) {
                case 'text':
                    return message.text; // 纯文本直接返回

                case 'voice_text':
                    return `[我发送了语音]: ${message.transcript}`;

                case 'html':
                // 如果是转账卡片 (html类型)，尝试提取金额告诉AI
                if (message.text && message.text.includes('转账')) {
                     return message.text; // 返回 "[转账：50.0]" 这种简略信息
                }
                return "[我渲染了一个HTML组件给用户]";

                // ▼▼▼ 核心修复：明确告诉 AI 它已经发过这些东西了 ▼▼▼
                case 'sticker':
                    // 告诉 AI：你已经发过这个表情了，别再发了！
                    const aiStickerName = message.text.includes('：') ? message.text.split('：')[1].replace(']', '') : '表情';
                    return `[我已发送表情包：${aiStickerName}]`;

                case 'image':
                    return `[我已发送了一张图片]`;

                case 'file_card':
                    return `[我已发送文件：${message.fileName}]`;

                case 'action':
                    return `(我执行了动作/旁白：${message.text})`;

                case 'call_summary':
                    // 摘要是系统消息，AI可以知道，但不作为对话内容
                    return `[系统记录：通话已结束并生成摘要]`;

                default:
                    // 处理转账等特殊文本
                    if (text.startsWith('[TRANSFER_START]')) {
                        // 提取转账金额和备注，告诉AI它转过账了
                        const match = text.match(/\[TRANSFER_START\](.*?)-([\d\.]+)\[TRANSFER_END\]/);
                        if (match) {
                            return `[我已转账 ¥${match[2]}，备注：${match[1]}]`;
                        }
                        return `[我已发起转账]`;
                    }
                    if (text.startsWith('[MUSIC_SHARE]')) {
                        return `[我已发送音乐分享邀请]`;
                    }
                    if (message.type === 'transfer_notify') {
                        return message.text; //把系统偷偷塞进去的“用户已拒绝”告诉AI
                    }
                    return message.text;
            }
        }
    }

