    /**
     * 【新增】一个更智能的AI调用函数，专门用于获取通话决策
     * @param {string} promptText - 发送给AI的特定指令
     * @param {object} contact - 当前联系人对象
     * @returns {Promise<string>} - 返回AI的决策关键词 ("ANSWER" 或 "REJECT")
     */
    async function fetchAiCallDecision(promptText, contact) {
        try {
            const settingsData = await dbHelper.loadData('settingsStore', 'apiSettings');
            if (!settingsData || !settingsData.value.url) throw new Error("API未配置");

            const { url, key, model } = settingsData.value;
            let completionsUrl = url.endsWith('/') ? url.slice(0, -1) : url;
            completionsUrl += '/chat/completions';

            // --- 核心区别：我们在这里加入了最近的聊天记录 ---
            const history = contact.history || [];
            const recentHistory = history.slice(-10); // 取最近10条消息作为参考
            const messages = [
                { role: "system", content: `你正在扮演角色 ${contact.ai.name} (${contact.ai.persona})。` }
            ];
            recentHistory.forEach(msg => {
                const contentForAI = translateMessageForAI(msg);
                if (contentForAI) {
                    messages.push({
                        role: msg.sender === 'user' ? 'user' : 'assistant',
                        content: contentForAI
                    });
                }
            });
            messages.push({ role: "user", content: promptText });
            // --- 历史记录添加结束 ---

            const response = await fetch(completionsUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${key}` },
                body: JSON.stringify({ model, messages, temperature: 0.7, max_tokens: 10 })
            });

            if (!response.ok) throw new Error(`API请求失败: ${response.status}`);
            const data = await response.json();
            return data.choices[0].message.content.trim();
        } catch (error) {
            console.error("获取AI通话决策失败:", error);
            return "REJECT"; // 如果出错，默认拒绝
        }
    }



