    /**
     * 根据指定的商品类别，渲染商品列表
     * @param {string} category - 商品类别 (例如 'takeout', 'electronics')
     */
    /**
     * 根据指定的商品类别，渲染商品列表 (V2 - 支持品牌标记)
     * @param {string} category - 商品类别 (例如 'takeout', 'electronics')
     */
    function renderProducts(category) {
        productGrid.innerHTML = ''; // 清空现有商品
        const items = productData[category] || []; // 获取对应类别的商品数组

        if (items.length === 0) {
            productGrid.innerHTML = '<p>该分类下暂无商品</p>';
            return;
        }

        items.forEach(item => {
            const card = document.createElement('div');
            card.className = 'product-card';

            // ▼▼▼ 核心修改：检查是否存在品牌信息，如果存在则生成品牌标签HTML ▼▼▼
            const brandTagHTML = item.brand ? `<div class="product-brand-tag">${item.brand}</div>` : '';
            // ▲▲▲ 修改结束 ▲▲▲

            card.innerHTML = `
            ${brandTagHTML} 
            <div class="product-name">${item.name}</div>
            <div class="product-description">${item.description}</div>
            <div class="product-footer">
                <span class="product-price">¥${item.price.toFixed(2)}</span>
                <button class="add-to-cart-btn">+</button>
            </div>
        `;
            productGrid.appendChild(card);
        });
    }

    // --- 事件监听 ---
