    // 3. 当用户选择了图片文件后，执行此函数
    chatImageUploadInput.addEventListener('change', (event) => {
        const file = event.target.files[0];
        if (!file) {
            return; // 如果用户取消了选择，则不执行任何操作
        }

        // 使用 FileReader 将图片文件转换为 Base64 格式
        const reader = new FileReader();
        reader.onload = (e) => {
            const imageDataUrl = e.target.result;

            // 创建一个图片消息对象
            const imageMessage = {
                sender: 'user',
                type: 'image', // 我们可以复用 sticker 的样式来显示图片
                url: imageDataUrl,
                text: '[图片]', // 这是给AI和历史记录看的内部文本
                timestamp: new Date(),
                uuid: Date.now() + '-' + Math.random().toString(36).substr(2, 9)
            };

            // 调用你已有的 sendMessage 函数来发送
            sendMessage(imageMessage);
        };
        reader.readAsDataURL(file);

        // 清空文件选择框的值，以便用户下次可以选择同一张图片
        event.target.value = '';
    });


