    // === 核心辅助函数：递归查找并插入 (请确保这段代码也在你的JS里) ===
    /**
     * 【核心修复】智能扁平化添加评论
     * 逻辑：无论回复的是层主还是楼中楼，新评论都作为“子评论”添加到该层主下。
     * 解决了“评论消失”和“层级乱窜”的问题。
     */
    function findCommentAndAddReply(comments, targetId, newReply) {
        if (!comments || !Array.isArray(comments)) return false;

        // 1. 遍历所有顶层评论（层主）
        for (let comment of comments) {
            // 情况 A：目标就是这个顶层评论 (用户直接回复层主)
            if (String(comment.id) === String(targetId)) {
                if (!comment.replies) comment.replies = [];
                comment.replies.push(newReply);
                return true;
            }

            // 情况 B：目标在这个顶层评论的子评论列表里 (用户回复了楼中楼)
            // 我们遍历子评论看是否存在 targetId
            if (comment.replies && comment.replies.length > 0) {
                // 检查子评论里有没有我们要回复的ID
                const isTargetInSub = comment.replies.some(sub => String(sub.id) === String(targetId));

                if (isTargetInSub) {
                    // 找到了！虽然是回复子评论，但我们把新数据 push 到【这一层】的 replies 里
                    // 这样它们就是并列显示的，符合“扁平化”视觉风格
                    // 此时 newReply.text 应该已经包含了 "回复 @某某："，所以不用担心逻辑混乱
                    comment.replies.push(newReply);
                    return true;
                }
            }
        }
        return false; // 没找到
    }

    // === 核心辅助函数：递归查找并插入回复 ===
    // 请确保这个函数在你的代码中存在，如果已存在请替换为这个强壮版本
    /**
     * 【核心修复】智能扁平化添加评论
     * 逻辑：无论回复的是层主还是楼中楼，新评论都作为“子评论”添加到该层主下。
     */
    function findCommentAndAddReply(comments, targetId, newReply) {
        if (!comments || !Array.isArray(comments)) return false;

        for (let comment of comments) {
            // 情况 A：目标就是这个顶层评论 (回复层主)
            if (String(comment.id) === String(targetId)) {
                if (!comment.replies) comment.replies = [];
                comment.replies.push(newReply);
                return true;
            }

            // 情况 B：目标在这个顶层评论的子评论列表里 (回复楼中楼)
            // 我们遍历子评论看是否存在 targetId
            if (comment.replies && comment.replies.length > 0) {
                // 检查子评论里有没有我们要回复的ID
                const isTargetInSub = comment.replies.some(sub => String(sub.id) === String(targetId));

                if (isTargetInSub) {
                    // 找到了！虽然是回复子评论，但我们把新数据 push 到【这一层】的 replies 里
                    // 这样它们就是并列显示的，符合“扁平化”视觉风格
                    comment.replies.push(newReply);
                    return true;
                }
            }
        }
        return false;
    }
    /**
     * 触发七浪 AI 回复
     */
    /**
     * 触发七浪 AI 回复 (修复版：确保楼中楼)
     */
    // 注意最后加了一个逗号和 contextPostId
    async function triggerQilangAiReply(targetName, userText, postContext, parentCommentId, contextPostId) {
        console.log(`AI 正在思考... 扮演: ${targetName}, 目标父ID: ${parentCommentId}`);

        const prompt = `(系统指令：扮演 "${targetName}"，在帖子评论区回复用户。用户说："${userText}"。请简短回怼或互动，30字以内。)`;

        const replyText = await fetchSimpleAiResponse(prompt);

        if (replyText) {
            safeTimeout(async () => {
                // 1. 构建 AI 回复对象
                const aiComment = {
                    id: `ai-${Date.now()}`,
                    user: targetName,
                    text: replyText,
                    replies: []
                };

                // 2. 读取并保存
                const postsData = await dbHelper.loadData('qilangPosts', 'allPosts');
                let allPosts = postsData.value;
                // 使用 String 比较 ID
                const index = allPosts.findIndex(p => String(p.id) === String(currentDetailPostId));

                if (index > -1) {
                    const currentPost = allPosts[index];

                    // 【核心】AI 回复也是楼中楼
                    // 它尝试找到 parentCommentId (你刚才发的评论ID) 并挂在下面
                    const success = findCommentAndAddReply(currentPost.comments, parentCommentId, aiComment);

                    if (!success) {
                        console.warn("AI回复找不到父节点，回退到顶层");
                        currentPost.comments.push(aiComment);
                    }

                    await dbHelper.saveData('qilangPosts', 'allPosts', allPosts);

                    // 3. 只有当用户还停留在当前帖子时，才刷新界面
                    if (currentDetailPostId === currentPost.id) {
                        openQilangDetail(currentPost);
                    }
                }

            }, Math.random() * 1000 + 1000);
        }
    }
