    /**
     * 核心函数：获取当前联系人可用的所有表情包（支持双重开关控制）
     * @param {object} contact - 当前联系人对象
     * @returns {Promise<Map>} - 返回一个 Map，键是表情名，值是URL
     */
    async function getAllAvailableStickersMap(contact) {
        let finalMap;

        // 1. 【新增逻辑】检查“预设表情包”开关
        // 默认为 true (开启)，除非用户明确关闭 (false)
        const isDefaultEnabled = contact.enableDefaultStickers !== false;

        if (isDefaultEnabled) {
            // 如果开启，以全局 stickerMap 为基础
            finalMap = new Map(stickerMap);
        } else {
            // 如果关闭，从一个空的 Map 开始
            finalMap = new Map();
        }

        // 2. 检查“世界书表情包”开关
        const isWBEnabled = contact.enableWBStickers !== false; // 默认为 true

        // 如果世界书开关关了，或者没有关联世界书，直接返回当前结果
        // 检查新旧两个关联字段
        const hasLinkedBooks = (contact.linkedWorldBookIds && contact.linkedWorldBookIds.length > 0) 
                            || (contact.linkedWorldBookGroupIds && contact.linkedWorldBookGroupIds.length > 0);
        
        if (!isWBEnabled || !hasLinkedBooks) {
            return finalMap;
        }

        try {
            // 3. 加载世界书数据
            const booksData = await dbHelper.loadData('worldBooks', 'allWorldBooks');
            const allBooks = (booksData && Array.isArray(booksData.value)) ? booksData.value : [];
            const requiredBookIds = new Set();

            // 4. 找出关联的书籍ID
            // 优先新版
            if (contact.linkedWorldBookIds && contact.linkedWorldBookIds.length > 0) {
                 contact.linkedWorldBookIds.forEach(id => requiredBookIds.add(id));
            } else {
                 // 回退旧版
                 const groupsData = await dbHelper.loadData('worldBookGroups', 'allGroups');
                 const allGroups = (groupsData && Array.isArray(groupsData.value)) ? groupsData.value : [];
                 const linkedGroupIds = new Set(contact.linkedWorldBookGroupIds || []);
                 allGroups.forEach(g => {
                    if (linkedGroupIds.has(g.id) && Array.isArray(g.bookIds)) {
                        g.bookIds.forEach(bid => requiredBookIds.add(bid));
                    }
                 });
            }

            // 5. 遍历书籍内容并提取正则
            const linkedBooks = allBooks.filter(b => requiredBookIds.has(b.id));
            const regex = /\[([^:\]]+):(https?:\/\/[^\]]+)\]/g;

            linkedBooks.forEach(book => {
                if (!book.content) return;
                const text = book.content;
                let match;
                while ((match = regex.exec(text)) !== null) {
                    const name = match[1].trim();
                    const url = match[2].trim();
                    // 存入 Map 
                    // 注意：如果名字和预设的一样，这里会覆盖预设的，这正好符合“世界书优先级更高”的逻辑
                    finalMap.set(name, url);
                }
            });

            console.log(`表情包加载完毕。预设:${isDefaultEnabled}, 世界书:${isWBEnabled}, 总数:${finalMap.size}`);

        } catch (e) {
            console.error("提取世界书表情包失败:", e);
        }

        return finalMap;
    }



    /**
     * 启动主动消息计时器
     * @param {number} contactId - 离开的联系人ID
     */
    function startProactiveTimer(contactId) {
        // 1. 检查总开关和白名单
        if (!proactiveConfig.enabled || !proactiveConfig.targets.includes(contactId)) {
            return;
        }

        // 2. 清除旧计时器（防止重复）
        stopProactiveTimer(contactId);

        console.log(`[主动消息] 开始为联系人 ${contactId} 计时: ${proactiveConfig.interval} 分钟`);

        // 3. 设置新计时器 (✅ 使用TimerManager统一管理)
        const delay = proactiveConfig.interval * 60 * 1000; // 分钟转毫秒

        proactiveTimers[contactId] = window.TimerManager.setTimeout(async () => {
            console.log(`[主动消息] 时间到！触发联系人 ${contactId}`);
            await triggerProactiveAI(contactId);
        }, delay, 'proactive');
    }

    /**
     * 停止/重置计时器
     * @param {number} contactId 
     */
    function stopProactiveTimer(contactId) {
        if (proactiveTimers[contactId]) {
            clearTimeout(proactiveTimers[contactId]);
            delete proactiveTimers[contactId];
            console.log(`[主动消息] 联系人 ${contactId} 计时已取消`);
        }
    }
    
    /**
     * 立即触发 AI 主动回复（不需要等待计时器）
     * 用于游戏结束等特殊场景
     * @param {number} contactId 
     */
    async function triggerProactiveMessage(contactId) {
        console.log(`[主动消息] 立即触发联系人 ${contactId} 的AI回复`);
        await triggerProactiveAI(contactId);
    }
    
    /**
     * 触发 AI 主动发送消息
     */
    /**
     * 触发 AI 主动发送消息 (修复版：读人设、读世界书、读历史、多气泡)
     */
    async function triggerProactiveAI(contactId) {
        // 1. 获取联系人信息
        const contact = await getContactById(contactId);
        if (!contact) return;

        // 2. 再次检查：如果用户现在正好在这个聊天窗口里，就不发了
        if (currentOpenContact && currentOpenContact.id === contactId) {
            return;
        }

        console.log(`[主动消息] 正在为 ${contact.ai.name} 构建上下文...`);

        // --- A. 准备数据：人设 ---
        const aiPersona = `姓名：${contact.ai.name}\n人设：${contact.ai.persona}`;
        const userPersona = `姓名：${contact.user.name}\n人设：${contact.user.persona}`;

        // --- B. 准备数据：聊天记录 (前情提要) ---
        const history = contact.history || [];
        // 取最近 15 条，避免 token 爆炸，但足够了解上下文
        const recentHistory = history.slice(-15);
        let chatHistoryText = recentHistory.map(msg => {
            // 简单清洗一下消息内容
            let content = msg.text || (msg.transcript) || '[多媒体/图片]';
            // 如果是用户发的
            const sender = msg.sender === 'user' ? contact.user.name : contact.ai.name;
            return `${sender}: ${content}`;
        }).join('\n');

        if (!chatHistoryText) chatHistoryText = "(暂无对话记录)";

        // --- C. 准备数据：世界书 (核心修复) ---
        let worldBookContent = "无特定世界观设定。";
        // 检查是否有关联的世界书组
        if (contact.linkedWorldBookGroupIds && contact.linkedWorldBookGroupIds.length > 0) {
            try {
                const groupsData = await dbHelper.loadData('worldBookGroups', 'allGroups');
                const allGroups = (groupsData && Array.isArray(groupsData.value)) ? groupsData.value : [];

                const booksData = await dbHelper.loadData('worldBooks', 'allWorldBooks');
                const allBooks = (booksData && Array.isArray(booksData.value)) ? booksData.value : [];

                const linkedGroupIds = new Set(contact.linkedWorldBookGroupIds);
                const requiredBookIds = new Set();

                // 找出所有需要的书ID
                allGroups.forEach(group => {
                    if (linkedGroupIds.has(group.id) && Array.isArray(group.bookIds)) {
                        group.bookIds.forEach(bookId => requiredBookIds.add(bookId));
                    }
                });

                // 提取内容
                const linkedBooksContent = allBooks
                    .filter(book => requiredBookIds.has(book.id))
                    .map(book => `【世界设定：${book.name}】\n${book.content}`)
                    .join('\n\n');

                if (linkedBooksContent) {
                    worldBookContent = linkedBooksContent;
                }
            } catch (e) {
                console.error("主动消息读取世界书失败:", e);
            }
        }

        // --- D. 构造 Prompt (强力指令版) ---
        // 获取用户自定义的风格指令
        const userStylePrompt = proactiveConfig.systemPrompt ? `\n[用户自定义风格指令]\n${proactiveConfig.systemPrompt}\n` : '';
        
        const triggerPrompt = `
[核心指令]
用户已经有 ${proactiveConfig.interval} 分钟没说话了。你现在必须**完全沉浸**在你的角色中，根据【前情提要】和【人设】，主动发起一个新的话题，或者继续之前的话题来引起用户的注意。
${userStylePrompt}

[强制格式要求]
1. **必须发送 2 到 3 句短消息**。不要只发一句！
2. **必须使用反斜杠 "\\" 来分隔每一句话**。
3. **严禁**出现 "系统提示"、"AI"、"回复" 等出戏的词汇。
4. **严禁**重复之前的最后一句话。

[参考范例]
正确格式：你在干嘛呢？\\我刚看到一个好玩的东西，想给你看看。
正确格式：好无聊啊...\\你怎么还不理我？\\是不是把你忘啦？

---
### 你的角色 (AI)
${aiPersona}

### 用户角色 (User)
${userPersona}

### 世界观知识库
${worldBookContent}

### 前情提要 (最近聊天)
${chatHistoryText}
---
请现在生成你的主动消息：
`;

        // 4. 调用 AI
        try {
            console.log(`正在请求 ${contact.ai.name} 的主动消息...`);
            const aiResponseRaw = await fetchSimpleAiResponse(triggerPrompt);

            if (aiResponseRaw) {
                // --- E. 后处理：拆分消息并保存 ---

                // 1. 按 \ 或 \n 拆分消息
                const messages = aiResponseRaw.split(/\\|\\n|\n/).map(t => t.trim()).filter(t => t);

                if (messages.length === 0) return;

                // 2. 逐条保存到数据库
                // 我们使用一个 Promise.all 或者循环来确保顺序保存
                for (const msgText of messages) {
                    const aiMessage = {
                        sender: 'ai',
                        text: msgText,
                        timestamp: new Date(),
                        uuid: Date.now() + '-' + Math.random().toString(36).substr(2, 9)
                    };
                    // 保存每一条
                    await saveMessageToHistory(aiMessage, contactId);
                }

                // 3. 弹出通知 (显示合并后的文本，或者第一句)
                // 为了通知看起来整洁，我们用空格连接显示
                const notificationText = messages.join(' ');
                pushNotificationToQueue(contact, notificationText);

                console.log(`[主动消息] 成功生成并保存了 ${messages.length} 条消息。`);
            }

        } catch (e) {
            console.error("主动消息触发失败:", e);
        }
    }
    /**
     * 将通知加入队列
     */
    function pushNotificationToQueue(contact, text) {
        bannerQueue.push({ contact, text });
        processNotificationQueue();
    }

    /**
     * 处理通知队列
     */
    function processNotificationQueue() {
        if (isBannerShowing || bannerQueue.length === 0) return;

        isBannerShowing = true;
        const { contact, text } = bannerQueue.shift();

        showGlassBanner(contact, text);
    }

    /**
     * 显示高斯模糊横幅
     */
    function showGlassBanner(contact, text) {
        const container = document.getElementById('notification-banner-container');
        const banner = document.createElement('div');
        banner.className = 'glass-banner';
        banner.innerHTML = `
        <img src="${contact.ai.avatar}">
        <div class="glass-banner-content">
            <div class="glass-banner-title">${contact.ai.name}</div>
            <div class="glass-banner-text">${text}</div>
        </div>
    `;

        // 点击横幅跳转
        banner.onclick = () => {
            // 关闭横幅
            banner.classList.remove('show');
            setTimeout(() => banner.remove(), 400);
            // 跳转
            openChatView(contact.id);
        };

        container.appendChild(banner);

        // 动画进场
        requestAnimationFrame(() => {
            banner.classList.add('show');
        });

        // 2秒后自动消失
        setTimeout(() => {
            banner.classList.remove('show');

            // 动画结束后移除元素并处理下一条
            setTimeout(() => {
                banner.remove();
                isBannerShowing = false;
                processNotificationQueue(); // 递归处理下一条
            }, 400); // 等待 CSS transition 结束
        }, 2500); // 停留时间 (2s + 进场冗余)
    }
    // --- 5. 设置加载与保存逻辑 (你提供的部分) ---

    async function loadProactiveSettings() {
        const data = await dbHelper.loadData('settingsStore', 'proactiveConfig');
        if (data && data.value) {
            proactiveConfig = data.value;
        }

        // UI 同步 - 同步两个页面的开关状态
        if (proactiveMasterSwitch) proactiveMasterSwitch.checked = proactiveConfig.enabled;
        const newSwitch = document.getElementById('proactive-master-switch-new');
        if (newSwitch) newSwitch.checked = proactiveConfig.enabled;
        
        if (proactiveIntervalSlider) {
            proactiveIntervalSlider.value = proactiveConfig.interval;
            updateProactiveSliderVisual(); // 更新自定义滑块视觉
        }
        if (proactiveIntervalDisplay) proactiveIntervalDisplay.textContent = `${proactiveConfig.interval} 分钟`;

        // 加载系统指令
        const promptTextarea = document.getElementById('proactive-system-prompt');
        if (promptTextarea && proactiveConfig.systemPrompt) {
            promptTextarea.value = proactiveConfig.systemPrompt;
            updateProactiveCharCount();
        }

        updateProactiveStatusText();
        await renderProactiveContactList();
    }

    // 更新自定义滑块视觉效果（填充条和拇指位置）
    function updateProactiveSliderVisual() {
        const slider = document.getElementById('proactive-interval-slider');
        const fill = document.getElementById('proactive-slider-fill');
        const thumb = document.getElementById('proactive-slider-thumb');
        const display = document.getElementById('proactive-interval-display');
        
        if (!slider || !fill || !thumb) return;
        
        const val = slider.value;
        const min = slider.min || 5;
        const max = slider.max || 60;
        const percent = ((val - min) / (max - min)) * 100;
        
        fill.style.width = percent + '%';
        thumb.style.left = `calc(${percent}% - 14px)`;
        if (display) display.textContent = `${val} 分钟`;
    }

    // 更新字符计数
    function updateProactiveCharCount() {
        const textarea = document.getElementById('proactive-system-prompt');
        const display = document.getElementById('proactive-char-display');
        if (!textarea || !display) return;
        
        const len = textarea.value.length;
        const max = textarea.maxLength || 500;
        display.textContent = `${len} / ${max} 字符`;
    }

    async function saveProactiveSettings() {
        // 优先从新页面的开关读取状态
        const newSwitch = document.getElementById('proactive-master-switch-new');
        if (newSwitch) {
            proactiveConfig.enabled = newSwitch.checked;
        } else if (proactiveMasterSwitch) {
            proactiveConfig.enabled = proactiveMasterSwitch.checked;
        }
        
        proactiveConfig.interval = proactiveIntervalSlider ? parseInt(proactiveIntervalSlider.value) : proactiveConfig.interval;
        
        // 保存系统指令
        const promptTextarea = document.getElementById('proactive-system-prompt');
        if (promptTextarea) {
            proactiveConfig.systemPrompt = promptTextarea.value;
        }

        await dbHelper.saveData('settingsStore', 'proactiveConfig', proactiveConfig);
        
        // 同步两个页面的开关状态
        if (proactiveMasterSwitch) proactiveMasterSwitch.checked = proactiveConfig.enabled;
        if (newSwitch) newSwitch.checked = proactiveConfig.enabled;
        
        updateProactiveStatusText();

        // 如果关闭了，清除所有计时器
        if (!proactiveConfig.enabled) {
            Object.keys(proactiveTimers).forEach(id => stopProactiveTimer(id));
        }
    }

    function updateProactiveStatusText() {
        if (!proactiveStatusText) return;
        if (proactiveConfig.enabled) {
            proactiveStatusText.textContent = `开启 (${proactiveConfig.interval}分钟)`;
            proactiveStatusText.style.color = '#007AFF';
        } else {
            proactiveStatusText.textContent = '已关闭';
            proactiveStatusText.style.color = '#8e8e93';
        }
    }

    async function renderProactiveContactList() {
        const contactsData = await dbHelper.loadData('messageContacts', 'allContacts');
        const contacts = (contactsData && contactsData.value) ? contactsData.value : [];

        if (!proactiveContactList) return;
        proactiveContactList.innerHTML = '';

        // 过滤可见联系人
        const visibleContacts = contacts.filter(c => !c.isHidden);
        
        if (visibleContacts.length === 0) {
            proactiveContactList.innerHTML = '<div class="proactive-agent-grid-empty">暂无可用角色</div>';
            return;
        }

        visibleContacts.forEach(contact => {
            const isSelected = proactiveConfig.targets.includes(contact.id);
            const div = document.createElement('div');
            div.className = 'proactive-agent-item' + (isSelected ? ' selected' : '');
            div.dataset.contactId = contact.id;
            div.innerHTML = `
                <div class="proactive-avatar-box">
                    <img src="${contact.ai.avatar}" alt="${contact.ai.name}" onerror="this.style.display='none'; this.parentElement.innerHTML='<span style=\\'font-size:18px;font-weight:700;\\'>${contact.ai.name.charAt(0)}</span>';">
                    <div class="proactive-check-badge">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor">
                            <polyline points="20 6 9 17 4 12"></polyline>
                        </svg>
                    </div>
                </div>
                <span class="proactive-agent-name">${contact.ai.name}</span>
            `;

            // 点击切换选中状态
            div.addEventListener('click', async () => {
                const id = parseInt(div.dataset.contactId);
                div.classList.toggle('selected');
                
                // 触觉反馈
                if (window.navigator && window.navigator.vibrate) {
                    window.navigator.vibrate(5);
                }
                
                if (div.classList.contains('selected')) {
                    if (!proactiveConfig.targets.includes(id)) {
                        proactiveConfig.targets.push(id);
                    }
                } else {
                    proactiveConfig.targets = proactiveConfig.targets.filter(tid => tid !== id);
                    stopProactiveTimer(id);
                }
                // 不立即保存，等用户点击保存按钮
            });

            proactiveContactList.appendChild(div);
        });
    }

