    /**
     * 触发哇呜的复杂后台交互
     * @param {number} postId - 当前帖子ID
     * @param {string} userContent - 用户刚刚发送的内容
     * @param {string|null} parentCommentId - 用户回复的根评论ID (null表示用户评论了帖子)
     * @param {string|null} replyToTargetUser - 用户具体回复的人名 (C回复B中的B)
     */
    // --- 2. 复杂交互调度器 (修复版：正确的楼层挂载) ---
    /**
     * 触发哇呜的复杂后台交互 (用户发帖/评论后的推演)
     */
    async function triggerWowComplexInteraction(postId, userContent, parentCommentId, replyToTargetUser, newUserCommentId) {
        const contact = currentWowContact;
        if (!contact) return;

        // 1. 读取世界书上下文 (关键！)
        let worldContext = await getWowWorldContextString(contact);

        const postsData = await dbHelper.loadData('wowPosts', 'allPosts');
        let allPosts = postsData.value;
        const post = allPosts.find(p => p.id === postId);
        if (!post) return;

        // 准备任务队列
        let replyTasks = [];

        // --- 场景判定 ---

        // 情况A：用户是在回复别人 (楼中楼)
        if (parentCommentId && replyToTargetUser) {
            // 目标必须回 (除非目标是自己)
            if (replyToTargetUser !== contact.user.name) {
                replyTasks.push({
                    speaker: replyToTargetUser,
                    targetParentId: parentCommentId,
                    targetUser: contact.user.name,
                    worldContext: worldContext, // 注入世界书
                    isMainAI: (replyToTargetUser === contact.ai.name)
                });
            }
        }
        // 情况B：用户直接评论/发布了帖子 (顶层)
        else {
            // 1. 帖子作者回（如果作者不是用户自己）
            if (post.author !== contact.user.name) {
                replyTasks.push({
                    speaker: post.author,
                    targetParentId: newUserCommentId,
                    targetUser: null,
                    worldContext: worldContext
                });
            }
            // 2. 如果是用户自己的帖子 -> 召唤主角AI + 随机路人
            else {
                // 主角AI必回
                replyTasks.push({
                    speaker: contact.ai.name,
                    targetParentId: newUserCommentId,
                    targetUser: null,
                    worldContext: worldContext,
                    isMainAI: true
                });

                // 随机生成 1-3 个路人/世界书NPC来凑热闹
                const randomCount = Math.floor(Math.random() * 3) + 1;
                for (let i = 0; i < randomCount; i++) {
                    replyTasks.push({
                        speaker: "RANDOM_NPC", // 标记为随机，让执行函数去生成名字
                        targetParentId: newUserCommentId,
                        worldContext: worldContext,
                        isMainAI: false
                    });
                }
            }
        }

        // 执行任务 (带延迟，模拟真实感)
        let delay = 2000;
        for (const task of replyTasks) {
            setTimeout(async () => {
                await executeWowReplyTask(task, post, userContent);
            }, delay);
            delay += Math.random() * 3000 + 2000;
        }
    }


   
