    // 调用MiniMax TTS API
    async function callMinimaxTTS(text, voiceId, language) {
        // 预处理: 去除首尾空格和换行，防止模型在句尾产生幻觉(杂音)
        if (text) text = text.trim().replace(/[\r\n]+/g, ' ');
        if (!dbHelper || !dbHelper.db) {
            throw new Error('数据库未初始化');
        }
        const config = await dbHelper.loadData('settingsStore', 'minimaxTTSConfig');
        if (!config || !config.value || !config.value.groupId || !config.value.apiKey) {
            throw new Error('MiniMax配置未完成');
        }

        const { groupId, apiKey, modelId } = config.value;
        
        // 【核心修复】使用有效的默认模型
        let finalModelId = modelId || 'speech-2.6-turbo';
        
        // 智能路由：根据模型选择正确的接口
        // speech-01 系列使用 t2a_pro，speech-02/2.6 系列使用 t2a_v2
        const isLegacyProModel = finalModelId.includes('speech-01');
        const apiPath = isLegacyProModel ? 't2a_pro' : 't2a_v2';
        
        const url = `https://api.minimax.chat/v1/${apiPath}?GroupId=${groupId}`;
        console.log(`[Minimax] 使用接口: ${apiPath} (模型: ${finalModelId})`);

        // 模型名称自动修正：API 严格要求完整模型名
        if (finalModelId === 'speech-01') finalModelId = 'speech-01-turbo';
        if (finalModelId === 'speech-02') finalModelId = 'speech-02-turbo'; // 默认为 turbo
        if (finalModelId === 'speech-2.6') finalModelId = 'speech-2.6-turbo'; // 默认为 turbo

        let requestBody;
        
        if (isLegacyProModel) {
            // t2a_pro 使用扁平化结构 (不支持 language_boost 或名字不同)
            requestBody = {
                model: finalModelId,
                text: text,
                voice_id: voiceId || 'female-shaonv',
                speed: 1.0,
                vol: 1.0,
                pitch: 0,
                audio_sample_rate: 32000,
                bitrate: 128000,
                format: 'mp3'
            };
        } else {
            // t2a_v2 使用嵌套结构，OpenAPI 显示支持 language_boost
            // 关键：Enum 映射必须严格匹配文档
            const langMap = {
                'zh-CN': 'Chinese',
                'zh-HK': 'Chinese,Yue', // 粤语必须传 "Chinese,Yue"
                'en-US': 'English',
                'ja-JP': 'Japanese',
                'ko-KR': 'Korean',
                'de-DE': 'German',
                'fr-FR': 'French',
                'es-ES': 'Spanish',
                'pt-BR': 'Portuguese',
                'ru-RU': 'Russian',
                'tr-TR': 'Turkish',
                'nl-NL': 'Dutch',
                'it-IT': 'Italian',
                'vi-VN': 'Vietnamese',
                'id-ID': 'Indonesian',
                'th-TH': 'Thai',
                'ms-MY': 'Malay',
                'ar-SA': 'Arabic',
                'hi-IN': 'Hindi',
                'pl-PL': 'Polish',
                'sv-SE': 'Swedish',
                'fi-FI': 'Finnish',
                'da-DK': 'Danish'
            };
            
            // 如果没找到映射，则不传或传 auto，避免传无效字符串导致报错
            const boostLang = (language && langMap[language]) ? langMap[language] : 'auto';

            requestBody = {
                model: finalModelId,
                text: text,
                stream: false,
                language_boost: boostLang,
                voice_setting: {
                    voice_id: voiceId || 'female-shaonv',
                    speed: 1.0,
                    vol: 1.0,
                    pitch: 0
                },
                audio_setting: {
                    format: 'mp3',
                    sample_rate: 32000,
                    bitrate: 128000,
                    channel: 1
                }
            };
        }

        const requestOptions = {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            },
            body: JSON.stringify(requestBody)
        };



        const response = await fetch(url, requestOptions);

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(`TTS API请求失败: ${response.status} - ${errorText}`);
        }

        const data = await response.json();
        console.log('[MiniMax TTS] API响应数据:', data);

        // 1. 检查 API 层面错误 (Minimax V2 标准)
        if (data.base_resp && data.base_resp.status_code !== 0) {
            throw new Error(`MiniMax API错误: [${data.base_resp.status_code}] ${data.base_resp.status_msg}`);
        }

        // 2. 提取音频数据
        // 优先级：data.data.audio (v2) > data.audio_file (v1) > extra_info.audio_file
        let audioContent = null;
        if (data.data && data.data.audio) {
            audioContent = data.data.audio;
        } else if (data.audio_file) {
            audioContent = data.audio_file;
        } else if (data.extra_info && data.extra_info.audio_file) {
            audioContent = data.extra_info.audio_file;
        }

        if (!audioContent) {
            throw new Error('API返回正常但未找到音频数据(audio/audio_file)');
        }

        // 3. 格式处理：Hex -> Base64
        // Minimax V2 经常返回 Hex 字符串。简单的启发式判断：如果不含 '+' '/' '=' 且全是 hex 字符，就视为 Hex
        // (Base64 可能包含 a-f 0-9 但通常会有 + / =，且 hex 看起来只有 0-9a-f)
        const isHex = /^[0-9a-fA-F]+$/.test(audioContent);
        
        if (isHex) {
            try {
                // Hex string to Uint8Array
                const match = audioContent.match(/.{1,2}/g);
                if (match) {
                    const bytes = new Uint8Array(match.map(byte => parseInt(byte, 16)));
                    // Uint8Array to Base64
                    let binary = '';
                    const len = bytes.byteLength;
                    for (let i = 0; i < len; i++) {
                        binary += String.fromCharCode(bytes[i]);
                    }
                    return window.btoa(binary);
                }
            } catch (e) {
                console.warn('[MiniMax TTS] Hex转换失败，尝试直接作为Base64使用', e);
            }
        }

        // 默认假设是 Base64
        return audioContent;
    }

