    // 播放TTS音频
    // === TTS 缓存管理 (IndexedDB) ===
    const TTSCache = {
        dbName: 'MinimaxTTSCache',
        storeName: 'audio_cache',
        _db: null,
        async getDB() {
            if (this._db) return this._db;
            return new Promise((resolve, reject) => {
                const req = indexedDB.open(this.dbName, 1);
                req.onupgradeneeded = (e) => {
                    const db = e.target.result;
                    if (!db.objectStoreNames.contains(this.storeName)) {
                        db.createObjectStore(this.storeName);
                    }
                };
                req.onsuccess = (e) => { this._db = e.target.result; resolve(this._db); };
                req.onerror = (e) => reject(e.target.error);
            });
        },
        async get(key) {
            try {
                const db = await this.getDB();
                return new Promise((resolve, reject) => {
                    const tx = db.transaction(this.storeName, 'readonly');
                    const req = tx.objectStore(this.storeName).get(key);
                    req.onsuccess = () => resolve(req.result);
                    req.onerror = () => reject(req.error);
                });
            } catch (e) { return null; }
        },
        async put(key, data) {
            try {
                const db = await this.getDB();
                return new Promise((resolve, reject) => {
                    const tx = db.transaction(this.storeName, 'readwrite');
                    tx.objectStore(this.storeName).put(data, key);
                    tx.oncomplete = () => resolve();
                    tx.onerror = () => reject();
                });
            } catch (e) {}
        },
        genKey(text, voiceId, lang) {
            // 简单hash防止key过长
            let hash = 0;
            if (!text) return 'empty';
            for (let i = 0; i < text.length; i++) {
                hash = ((hash << 5) - hash) + text.charCodeAt(i);
                hash |= 0;
            }
            // 使用 前20字符 + hash 组合作为key，既直观又唯一
            const prefix = text.substring(0, 20).replace(/[^\w\u4e00-\u9fa5]/g, '_'); 
            return `${voiceId || 'def'}_${lang || 'auto'}_${prefix}_${hash}`;
        },
        // iOS内存优化：清空所有缓存
        async clear() {
            try {
                const db = await this.getDB();
                return new Promise((resolve, reject) => {
                    const tx = db.transaction(this.storeName, 'readwrite');
                    tx.objectStore(this.storeName).clear();
                    tx.oncomplete = () => {
                        console.log('[TTSCache] 缓存已清空');
                        resolve();
                    };
                    tx.onerror = () => reject();
                });
            } catch (e) { console.warn('[TTSCache] 清空失败', e); }
        },
        // iOS内存优化：只保留最近N条缓存
        async cleanup(keepCount = 10) {
            try {
                const db = await this.getDB();
                const tx = db.transaction(this.storeName, 'readwrite');
                const store = tx.objectStore(this.storeName);
                const keys = await new Promise((resolve, reject) => {
                    const req = store.getAllKeys();
                    req.onsuccess = () => resolve(req.result);
                    req.onerror = () => reject(req.error);
                });
                
                if (keys.length > keepCount) {
                    // 删除最旧的记录（假设key按时间顺序）
                    const toDelete = keys.slice(0, keys.length - keepCount);
                    for (const key of toDelete) {
                        store.delete(key);
                    }
                    console.log(`[TTSCache] 清理了 ${toDelete.length} 条旧缓存`);
                }
            } catch (e) { console.warn('[TTSCache] 清理失败', e); }
        }
    };
    
    // 暴露到window供iOS内存优化器调用
    window.TTSCache = TTSCache;

    // 播放TTS音频 (带缓存)
    async function playTTS(text, voiceId, language) {
        try {
            // 1. 预处理文本 (保持与 callMinimaxTTS 一致)
            if (!text) return false;
            text = text.trim().replace(/[\r\n]+/g, ' ');
            
            // 2. 停止当前播放
            if (currentTTSAudio) {
                currentTTSAudio.pause();
                currentTTSAudio = null;
            }
            // iOS内存优化：释放之前的ObjectURL
            if (currentTTSAudioUrl) {
                URL.revokeObjectURL(currentTTSAudioUrl);
                currentTTSAudioUrl = null;
            }
            
            // 3. 检查缓存
            const cacheKey = TTSCache.genKey(text, voiceId, language);
            let audioData = await TTSCache.get(cacheKey);
            let fromCache = !!audioData;

            if (fromCache) {
                console.log('[Minimax TTS] 🚀 命中缓存，省钱了！');
            } else {
                console.log('[Minimax TTS] 💨 未命中缓存，调用API...');
                audioData = await callMinimaxTTS(text, voiceId, language);
                if (audioData) {
                     // 存入缓存
                     TTSCache.put(cacheKey, audioData).catch(err => console.warn('Cache put failed', err));
                }
            }

            // 4. 播放
            if (!audioData) return false;

            let audioUrl;
            if (typeof audioData === 'string' && audioData.startsWith('http')) {
                audioUrl = audioData;
                currentTTSAudioUrl = null; // URL类型不需要revoke
            } else {
                const audioBlob = base64ToBlob(audioData, 'audio/mpeg');
                audioUrl = URL.createObjectURL(audioBlob);
                currentTTSAudioUrl = audioUrl; // iOS内存优化：记录URL以便后续释放
            }

            currentTTSAudio = new Audio(audioUrl);
            currentTTSAudio.play().catch(e => console.error('Audio play error:', e));

            currentTTSAudio.onended = () => {
                if (currentTTSAudioUrl) {
                    URL.revokeObjectURL(currentTTSAudioUrl);
                    currentTTSAudioUrl = null;
                }
                currentTTSAudio = null;
            };

            return true;
        } catch (e) {
            console.error('[MiniMax TTS] 播放失败', e);
            throw e;
        }
    }

    // Base64转Blob
    function base64ToBlob(base64, mimeType) {
        const byteCharacters = atob(base64);
        const byteNumbers = new Array(byteCharacters.length);
        for (let i = 0; i < byteCharacters.length; i++) {
            byteNumbers[i] = byteCharacters.charCodeAt(i);
        }
        const byteArray = new Uint8Array(byteNumbers);
        return new Blob([byteArray], { type: mimeType });
    }

